using System;using P3.Validation;using UnityEngine;
public static class P3ArtValidationSmokeTest{public static void Run(){foreach(var id in new[]{"art_focus","art_runtime","art_iteration","t0_art_seal"}){var p=ProfileRegistry.GetArt(id);if(p.ExternalReviewRequired.Count==0)throw new Exception("review not required");if(p.RequiredSteps.Exists(x=>x.Contains("p0")))throw new Exception("program mutation leaked");}bool rejected=false;try{ArtIterationService.Validate(new ArtIterationRequest{TargetId="../raw",Action=ArtIterationAction.BindApprovedVisualId,StringValue="Assets/x"});}catch{rejected=true;}if(!rejected)throw new Exception("unsafe iteration accepted");Debug.Log("P3 Art Validation PASSED");}}
